import{_ as t,a0 as p,w as h,s as d,I as l,x as e,a1 as a,A as n,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"如何在 Linux 中启用 Shell 脚本的调试模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中启用 Shell 脚本的调试模式 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中启用 Shell 脚本的调试模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中启用 Shell 脚本的调试模式 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/2016118-How-To-Enable-Shell-Script-Debugging Mode in Linux","title":"如何在 Linux 中启用 Shell 脚本的调试模式","tag":"201612","desc":""},"relativePath":"201612/2016118-How-To-Enable-Shell-Script-Debugging Mode in Linux.md","filePath":"[post].md"}'),r={name:"201612/2016118-How-To-Enable-Shell-Script-Debugging Mode in Linux.md"};function g(b,s,k,u,c,f){const i=p("Link");return h(),d("div",null,[s[19]||(s[19]=l("h1",{id:"如何在-linux-中启用-shell-脚本的调试模式",tabindex:"-1"},[e("如何在 Linux 中启用 Shell 脚本的调试模式 "),l("a",{class:"header-anchor",href:"#如何在-linux-中启用-shell-脚本的调试模式","aria-label":"Permalink to “如何在 Linux 中启用 Shell 脚本的调试模式”"},"​")],-1)),s[20]||(s[20]=l("p",null,"脚本是存储在一个文件的一系列命令。在终端上输入一个个命令，按顺序执行的方法太弱了，使用脚本，系统中的用户可以在一个文件中存储所有命令，反复调用该文件多次重新执行命令。",-1)),l("p",null,[s[1]||(s[1]=e("在 ",-1)),a(i,{href:"http://www.tecmint.com/category/bash-shell/"},{default:n(()=>[...s[0]||(s[0]=[e("学习脚本",-1)])]),_:1}),s[2]||(s[2]=e(" 或写脚本的初期阶段，我们通常从写小脚本或者几行命令的短脚本开始，调试这样的脚本时我们通常无非就是通过观察它们的输出来确保其正常工作。",-1))]),l("p",null,[s[4]||(s[4]=e("然而，当我们开始写非常长或上千行命令的高级脚本，例如改变系统设置的脚本，",-1)),a(i,{href:"http://www.tecmint.com/rsync-local-remote-file-synchronization-commands/"},{default:n(()=>[...s[3]||(s[3]=[e("在网络上执行关键备份",-1)])]),_:1}),s[5]||(s[5]=e(" 等等，我们会意识到仅仅看脚本输出是不足以在脚本中找到 Bug 的！",-1))]),s[21]||(s[21]=o(`<p>因此，在 Linux 系列中这篇介绍 Shell 脚本调试， 我们将看看如何启用 Shell 脚本调试，然后在之后的系列中解释不同的 Shell 脚本调试模式以及如何使用它们。</p><h3 id="如何开始写一个脚本" tabindex="-1">如何开始写一个脚本 <a class="header-anchor" href="#如何开始写一个脚本" aria-label="Permalink to “如何开始写一个脚本”">​</a></h3><p>一个脚本与其它文件的区别是它的首行，它包含 <code>#!</code> （She-Bang - 释伴：定义文件类型）和路径名（解释器路径），通知系统该文件是一个命令集合，将被指定程序(解释器)解释。</p><p>下面是不同类型脚本 <code>首行</code> 示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh          [sh 脚本]</span></span>
<span class="line"><span>#!/bin/bash        [bash 脚本] </span></span>
<span class="line"><span>#!/usr/bin/perl    [perl 程序]</span></span>
<span class="line"><span>#!/bin/awk -f      [awk 脚本]</span></span></code></pre></div><p>注意：如果脚本仅包含一组标准系统命令，没有任何内部 Shell 指令，首行或 <code>#!</code> 可以去掉。</p><h3 id="如何在-linux-操作系统执行-shell-脚本" tabindex="-1">如何在 Linux 操作系统执行 Shell 脚本 <a class="header-anchor" href="#如何在-linux-操作系统执行-shell-脚本" aria-label="Permalink to “如何在 Linux 操作系统执行 Shell 脚本”">​</a></h3><p>调用一个脚本脚本的常规语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ 脚本名  参数1 ... 参数N</span></span></code></pre></div><p>另一种可能的形式是明确指定将执行这个脚本的 Shell，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shell 脚本名  参数1 ... 参数N</span></span></code></pre></div><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /bin/bash   参数1 ... 参数N     [bash 脚本]</span></span>
<span class="line"><span>$ /bin/ksh   参数1 ... 参数N      [ksh 脚本]</span></span>
<span class="line"><span>$ /bin/sh   参数1 ... 参数N       [sh 脚本]</span></span></code></pre></div><p>对于没有 <code>#!</code> 作为首行，仅包含基础系统命令的脚本，示例如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### 脚本仅包含标准系统命令</span></span>
<span class="line"><span>cd /home/$USER</span></span>
<span class="line"><span>mkdir tmp</span></span>
<span class="line"><span>echo &quot;tmp directory created under /home/$USER&quot;</span></span></code></pre></div><p>使它可执行并运行，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x  脚本名</span></span>
<span class="line"><span>$ ./脚本名</span></span></code></pre></div><h3 id="启用-shell-脚本调试模式的方法" tabindex="-1">启用 Shell 脚本调试模式的方法 <a class="header-anchor" href="#启用-shell-脚本调试模式的方法" aria-label="Permalink to “启用 Shell 脚本调试模式的方法”">​</a></h3><p>下面是主要的 Shell 脚本调试选项：</p><ul><li><code>-v</code> （verbose 的简称） - 告诉 Shell 读取脚本时显示所有行，激活详细模式。</li><li><code>-n</code> （noexec 或 no ecxecution 简称） - 指示 Shell 读取所有命令然而不执行它们，这个选项激活语法检查模式。</li><li><code>-x</code> （xtrace 或 execution trace 简称） - 告诉 Shell 在终端显示所有执行的命令和它们的参数。 这个选项是启用 Shell 跟踪模式。</li></ul><h4 id="_1、-改变-shell-脚本首行" tabindex="-1">1、 改变 Shell 脚本首行 <a class="header-anchor" href="#_1、-改变-shell-脚本首行" aria-label="Permalink to “1、 改变 Shell 脚本首行”">​</a></h4><p>第一个机制是改变 Shell 脚本首行，如下，这会启动脚本调试。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh 选项</span></span></code></pre></div><p>其中， 选项可以是上面提到的一个或多个调试选项。</p><h4 id="_2、-调用-shell-调试选项" tabindex="-1">2、 调用 Shell 调试选项 <a class="header-anchor" href="#_2、-调用-shell-调试选项" aria-label="Permalink to “2、 调用 Shell 调试选项”">​</a></h4><p>第二个是使用如下调试选项启动 Shell，这个方法也会打开整个脚本调试。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shell 选项   参数1 ... 参数N</span></span></code></pre></div><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /bin/bash 选项   参数1 ... 参数N</span></span></code></pre></div><h4 id="_3、-使用-shell-内置命令-set" tabindex="-1">3、 使用 Shell 内置命令 set <a class="header-anchor" href="#_3、-使用-shell-内置命令-set" aria-label="Permalink to “3、 使用 Shell 内置命令 set”">​</a></h4><p>第三个方法是使用内置命令 <code>set</code> 去调试一个给定的 Shell 脚本部分，如一个函数。这个机制是重要的，因为它让我们可以去调试任何一段 Shell 脚本。</p><p>我们可以如下使用 <code>set</code> 命令打开调试模式，其中选项是之前提到的所有调试选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set 选项</span></span></code></pre></div><p>启用调试模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set -选项</span></span></code></pre></div><p>禁用调试模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set +选项</span></span></code></pre></div><p>此外，如果我们在 Shell 脚本不同部分启用了几个调试模式，我们可以一次禁用所有调试模式，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set -</span></span></code></pre></div><p>关于启用 Shell 脚本调试模式，先讲这些。正如我们看到的，我们可以调试一整个 Shell 脚本或者特定部分脚本。</p><p>在此系列下面的两篇文章中，我们会举例介绍如何使用 Shell 脚本调试选项，进一步了解 详细（verbose）、语法检查（syntax checking）、 跟踪（tracing）调试模式。</p><p>更重要的是，关于这个指南，欢迎通过下面评论提出任何问题或反馈。</p><hr>`,43)),l("p",null,[s[7]||(s[7]=e("via: ",-1)),a(i,{href:"http://www.tecmint.com/enable-shell-debug-mode-linux/"},{default:n(()=>[...s[6]||(s[6]=[e("http://www.tecmint.com/enable-shell-debug-mode-linux/",-1)])]),_:1})]),l("p",null,[s[11]||(s[11]=e("作者：",-1)),a(i,{href:"http://www.tecmint.com/author/aaronkili/"},{default:n(()=>[...s[8]||(s[8]=[e("Aaron Kili",-1)])]),_:1}),s[12]||(s[12]=e(" 译者：",-1)),a(i,{href:"https://github.com/imxieke"},{default:n(()=>[...s[9]||(s[9]=[e("imxieke",-1)])]),_:1}),s[13]||(s[13]=e(" 校对：",-1)),a(i,{href:"https://github.com/jasminepeng"},{default:n(()=>[...s[10]||(s[10]=[e("jasminepeng",-1)])]),_:1})]),l("p",null,[s[16]||(s[16]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[14]||(s[14]=[e("LCTT",-1)])]),_:1}),s[17]||(s[17]=e(" 组织编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[15]||(s[15]=[e("Linux中国",-1)])]),_:1}),s[18]||(s[18]=e(" 荣誉推出",-1))])])}const y=t(r,[["render",g]]);export{S as __pageData,y as default};
